package com.hooks.pingme;import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration;import org.springframework.boot.autoconfigure.orm.jpa.HibernateJpaAutoConfiguration;// Exclude DB auto-configuration so the app doesn't crash looking for a database@SpringBootApplication(exclude = {DataSourceAutoConfiguration.class, HibernateJpaAutoConfiguration.class})public class PingmeApplication {	public static void main(String[] args) {		SpringApplication.run(PingmeApplication.class, args);	}}